import java.util.*;

class Solution {
    public int totalFruit(int[] fruits) {
        Map<Integer, Integer> count = new HashMap<>();
        int maxLen = 0;
        int left = 0;

        for (int right = 0; right < fruits.length; right++) {
            count.put(fruits[right], count.getOrDefault(fruits[right], 0) + 1);

            // Shrink window if more than 2 types
            while (count.size() > 2) {
                int leftFruit = fruits[left];
                count.put(leftFruit, count.get(leftFruit) - 1);
                if (count.get(leftFruit) == 0) {
                    count.remove(leftFruit);
                }
                left++;
            }

            maxLen = Math.max(maxLen, right - left + 1);
        }

        return maxLen;
    }
}

class Solution {
    public int totalFruit(int[] fruits) {
        int n = fruits.length;
        int[] count = new int[n]; // fruit[i] < fruits.length
        int distinct = 0;
        int maxLen = 0;
        int left = 0;

        for (int right = 0; right < n; right++) {
            if (count[fruits[right]] == 0) distinct++;
            count[fruits[right]]++;

            while (distinct > 2) {
                count[fruits[left]]--;
                if (count[fruits[left]] == 0) distinct--;
                left++;
            }

            maxLen = Math.max(maxLen, right - left + 1);
        }

        return maxLen;
    }
}

import java.util.*;

class Solution {
    public int totalFruit(int[] fruits) {
        Map<Integer, Integer> lastSeen = new HashMap<>(); // fruit -> last index
        int maxLen = 0;
        int left = 0;

        for (int right = 0; right < fruits.length; right++) {
            lastSeen.put(fruits[right], right);

            if (lastSeen.size() > 2) {
                // Find fruit with earliest last occurrence
                int minIdx = Integer.MAX_VALUE;
                int toRemove = 0;
                for (Map.Entry<Integer, Integer> entry : lastSeen.entrySet()) {
                    if (entry.getValue() < minIdx) {
                        minIdx = entry.getValue();
                        toRemove = entry.getKey();
                    }
                }
                left = minIdx + 1;
                lastSeen.remove(toRemove);
            }

            maxLen = Math.max(maxLen, right - left + 1);
        }

        return maxLen;
    }
}
